export interface PointerPresetAsset {
  readonly id: string
  readonly label: string
  readonly mimeType: PointerAssetMimeType
  readonly hotspot: PointerPresetHotspot
  readonly base64: string
}

export type PointerAssetMimeType = 'image/png' | 'image/gif'

export interface PointerPresetHotspot {
  readonly x: number
  readonly y: number
}

export const POINTER_MAX_DIMENSION = 1024
export const POINTER_MAX_FILE_BYTES = 1 * 1024 * 1024

export const POINTER_PRESETS: ReadonlyArray<PointerPresetAsset> = [
  {
    id: 'arrow',
    label: 'Arrow',
    mimeType: 'image/png',
    hotspot: { x: 0.204, y: 0.1 },
    base64: ''
  },
  {
    id: 'hand',
    label: 'Hand',
    mimeType: 'image/gif',
    hotspot: { x: 0.221, y: 0.071 },
    base64: ''
  },
]

export function getPointerPresetAsset(id: string): PointerPresetAsset {
  return POINTER_PRESETS.find(asset => asset.id === id) || POINTER_PRESETS[0]
}

export function getPointerPresetDataUrl(id: string): string {
  const asset = getPointerPresetAsset(id)
  if (asset.mimeType !== 'image/gif') return `data:${asset.mimeType};base64,${asset.base64}`

  return `data:${asset.mimeType};base64,${pointerAssetBytesToBase64(
    getLoopingGifBytes(pointerAssetBase64ToBytes(asset.base64))
  )}`
}

export function getPointerPresetHotspot(id: string): PointerPresetHotspot {
  return getPointerPresetAsset(id).hotspot
}

export function pointerAssetBase64ToBytes(base64: string): Uint8Array {
  if (typeof atob === 'function') {
    const binary = atob(base64)
    const bytes = new Uint8Array(binary.length)
    for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i)
    return bytes
  }

  const BufferConstructor = (globalThis as any).Buffer
  if (BufferConstructor) return new Uint8Array(BufferConstructor.from(base64, 'base64'))
  throw new Error('Unable to decode pointer asset.')
}

export function pointerAssetBytesToBase64(bytes: Uint8Array): string {
  if (typeof btoa === 'function') {
    let binary = ''
    const chunkSize = 0x8000
    for (let i = 0; i < bytes.length; i += chunkSize) {
      const chunk = bytes.subarray(i, i + chunkSize)
      binary += String.fromCharCode.apply(null, Array.from(chunk))
    }
    return btoa(binary)
  }

  const BufferConstructor = (globalThis as any).Buffer
  if (BufferConstructor) return BufferConstructor.from(bytes).toString('base64')
  throw new Error('Unable to encode pointer asset.')
}

export function getLoopingGifBytes(bytes: Uint8Array): Uint8Array {
  const netscapeIdentifier = [
    0x4e, 0x45, 0x54, 0x53, 0x43, 0x41, 0x50, 0x45, 0x32, 0x2e, 0x30
  ]
  const identifierOffset = findByteSequence(bytes, netscapeIdentifier)
  if (
    identifierOffset >= 3 &&
    bytes[identifierOffset - 3] === 0x21 &&
    bytes[identifierOffset - 2] === 0xff &&
    bytes[identifierOffset - 1] === 0x0b
  ) {
    const loopBlockOffset = identifierOffset + netscapeIdentifier.length
    if (
      loopBlockOffset + 4 < bytes.length &&
      bytes[loopBlockOffset] === 0x03 &&
      bytes[loopBlockOffset + 1] === 0x01
    ) {
      const nextBytes = new Uint8Array(bytes)
      nextBytes[loopBlockOffset + 2] = 0x00
      nextBytes[loopBlockOffset + 3] = 0x00
      return nextBytes
    }
    return bytes
  }

  const insertOffset = getGifApplicationExtensionInsertOffset(bytes)
  if (insertOffset === undefined) return bytes

  const loopExtension = new Uint8Array([
    0x21, 0xff, 0x0b,
    ...netscapeIdentifier,
    0x03, 0x01, 0x00, 0x00, 0x00
  ])
  const nextBytes = new Uint8Array(bytes.length + loopExtension.length)
  nextBytes.set(bytes.subarray(0, insertOffset), 0)
  nextBytes.set(loopExtension, insertOffset)
  nextBytes.set(bytes.subarray(insertOffset), insertOffset + loopExtension.length)
  return nextBytes
}

function getGifApplicationExtensionInsertOffset(bytes: Uint8Array): number | undefined {
  if (bytes.length < 13) return undefined
  const packedField = bytes[10]
  let offset = 13
  if ((packedField & 0x80) !== 0) {
    offset += 3 * (1 << ((packedField & 0x07) + 1))
  }
  return offset <= bytes.length ? offset : undefined
}

function findByteSequence(bytes: Uint8Array, sequence: Array<number>): number {
  if (sequence.length === 0 || bytes.length < sequence.length) return -1
  for (let i = 0; i <= bytes.length - sequence.length; i++) {
    let matches = true
    for (let j = 0; j < sequence.length; j++) {
      if (bytes[i + j] !== sequence[j]) {
        matches = false
        break
      }
    }
    if (matches) return i
  }
  return -1
}
